    const { svc, tips } = getDeclarationAmounts(emp);
    const SVC_TOKEN = "@@PAYROLL_DECL_SVC@@";
    const TIPS_TOKEN = "@@PAYROLL_DECL_TIPS@@";
    const marked = tpl
      .replace(/\\$\\{svc_amount\\}/g, SVC_TOKEN)
